#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_repeat_interleave.h"

namespace ascend_kernel {

at::Tensor repeat_interleave(const at::Tensor &self, int64_t repeats, int64_t dim)
{
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "repeat_interleave: only float16, float32 and bfloat16 are supported, got ", self.scalar_type());
    TORCH_CHECK(repeats >= 1, "repeat_interleave: repeats must be >= 1, got ", repeats);
    TORCH_CHECK(self.dim() > 0, "repeat_interleave: input must have at least 1 dimension");
    TORCH_CHECK(self.is_contiguous(), "repeat_interleave: input must be contiguous");

    int64_t ndim = self.dim();
    if (dim < 0) {
        dim += ndim;
    }
    TORCH_CHECK(dim >= 0 && dim < ndim, "repeat_interleave: dim ", dim, " out of range for tensor with ", ndim, " dimensions");

    auto outputSizes = self.sizes().vec();
    outputSizes[dim] = self.size(dim) * repeats;
    at::Tensor output = at::empty(outputSizes, self.options());

    if (self.numel() == 0) {
        return output;
    }

    int64_t dtypeSize = static_cast<int64_t>(self.element_size());

    int64_t outerSize = 1;
    for (int64_t i = 0; i < dim; ++i) {
        outerSize *= self.size(i);
    }
    int64_t srcDimSize = self.size(dim);
    int64_t innerSize = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) {
        innerSize *= self.size(i);
    }

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    int64_t totalLengthCore = (outerSize + coreNum - 1) / coreNum;
    int64_t formerNum = outerSize % totalLengthCore == 0 ? coreNum : outerSize % totalLengthCore;
    int64_t tailNum = coreNum - formerNum;
    int64_t formerLength = (outerSize + coreNum - 1) / coreNum;
    int64_t tailLength = outerSize / coreNum;

    if (formerNum == 0) {
        formerNum = coreNum;
        tailNum = 0;
        formerLength = 1;
        tailLength = 0;
    }

    int64_t bufferCoefficient = dtypeSize * 4;
    if (bufferCoefficient == 0) {
        bufferCoefficient = 1;
    }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    if (alignElements == 0) {
        alignElements = 1;
    }
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength > innerSize) {
        tileLength = innerSize;
    }
    tileLength = (tileLength / alignElements) * alignElements;
    if (tileLength < alignElements) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(coreNum);

    int64_t outerSizeVal = outerSize;
    int64_t srcDimSizeVal = srcDimSize;
    int64_t innerSizeVal = innerSize;
    int64_t repeatsVal = repeats;
    int64_t formerNumVal = formerNum;
    int64_t formerLengthVal = formerLength;
    int64_t tailNumVal = tailNum;
    int64_t tailLengthVal = tailLength;
    int64_t tileLengthVal = tileLength;
    int64_t dtypeSizeVal = dtypeSize;

    EXEC_KERNEL_CMD(repeat_interleave, blockDim,
                    self, output,
                    outerSizeVal, srcDimSizeVal, innerSizeVal, repeatsVal,
                    formerNumVal, formerLengthVal, tailNumVal, tailLengthVal,
                    tileLengthVal, dtypeSizeVal);

    return output;
}

}  // namespace ascend_kernel
