21	                                int64_t outerSize, int64_t srcDimSize, int64_t innerSize,
22	                                int64_t repeats,
23	                                int64_t formerNum, int64_t formerLength,
24	                                int64_t tailNum, int64_t tailLength,
25	                                int64_t tileLength)
26	    {
27	        int64_t blockIdx = AscendC::GetBlockIdx();
28	
