56	    {
57	        int64_t srcOuterStride = srcDimSize * innerSize;
58	        int64_t dstOuterStride = srcDimSize * repeats * innerSize;
59	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
60	
61	        for (int64_t outer = 0; outer < coreOuterNum; ++outer) {
62	            int64_t currentOuter = coreOuterStart + outer;
63	            int64_t srcBase = currentOuter * srcOuterStride;
64	            int64_t dstBase = currentOuter * dstOuterStride;
65	
66	            for (int64_t srcIdx = 0; srcIdx < srcDimSize; ++srcIdx) {
67	                int64_t srcOffset = srcBase + srcIdx * innerSize;
68	
69	                int64_t tileNum = (innerSize + tileLength - 1) / tileLength;
70	                int64_t tailTileLength = innerSize - (tileNum - 1) * tileLength;
71	                int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
72	
73	                for (int64_t t = 0; t < tileNum; ++t) {
74	                    int64_t curTileLen = (t < tileNum - 1) ? tileLength :
