#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelRepeatInterleave {
public:
    __aicore__ inline KernelRepeatInterleave() {}

    __aicore__ inline void Init(GM_ADDR self, GM_ADDR out,
                                int64_t outerSize, int64_t srcDimSize, int64_t innerSize,
                                int64_t repeats,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailNum, int64_t tailLength,
                                int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        this->outerSize = outerSize;
        this->srcDimSize = srcDimSize;
        this->innerSize = innerSize;
        this->repeats = repeats;
        this->tileLength = tileLength;

        int64_t usedCoreNum = formerNum + tailNum;
        if (usedCoreNum == 0) {
            usedCoreNum = 1;
        }

        if (blockIdx >= usedCoreNum) {
            this->coreOuterStart = 0;
            this->coreOuterNum = 0;
            return;
        }

        int64_t coreOuterNum = (blockIdx < formerNum) ? formerLength : tailLength;
        int64_t outerStart = 0;
        if (blockIdx < formerNum) {
            outerStart = blockIdx * formerLength;
        } else {
            outerStart = formerNum * formerLength + (blockIdx - formerNum) * tailLength;
        }
        this->coreOuterStart = outerStart;
        this->coreOuterNum = coreOuterNum;

        int64_t srcOuterStride = srcDimSize * innerSize;
        int64_t dstOuterStride = srcDimSize * repeats * innerSize;

        selfGm.SetGlobalBuffer((__gm__ T *)self, outerSize * srcOuterStride);
        outGm.SetGlobalBuffer((__gm__ T *)out, outerSize * dstOuterStride);

        pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        if (coreOuterNum <= 0) {
            return;
        }

        int64_t srcOuterStride = srcDimSize * innerSize;
        int64_t dstOuterStride = srcDimSize * repeats * innerSize;
        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));

        for (int64_t outer = 0; outer < coreOuterNum; ++outer) {
            int64_t currentOuter = coreOuterStart + outer;
            if (currentOuter >= outerSize) {
                continue;
            }
            int64_t srcBase = currentOuter * srcOuterStride;
            int64_t dstBase = currentOuter * dstOuterStride;

            for (int64_t srcIdx = 0; srcIdx < srcDimSize; ++srcIdx) {
                int64_t srcOffset = srcBase + srcIdx * innerSize;

                int64_t tileNum = (innerSize + tileLength - 1) / tileLength;
                int64_t tailTileLength = innerSize - (tileNum - 1) * tileLength;
                int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

                for (int64_t t = 0; t < tileNum; ++t) {
                    int64_t curTileLen = (t < tileNum - 1) ? tileLength :
                                         ((tailTileLength > 0) ? alignedTailLen : tileLength);
                    if (t == tileNum - 1 && tailTileLength == 0) {
                        continue;
                    }

                    int64_t curSrcOffset = srcOffset + t * tileLength;

                    CopyIn(curSrcOffset, curTileLen);

                    AscendC::LocalTensor<T> inLocal = inQueue.DeQue<T>();
                    AscendC::LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
                    AscendC::DataCopy(outLocal, inLocal, curTileLen);
                    outQueue.EnQue<T>(outLocal);
                    inQueue.FreeTensor(inLocal);

                    AscendC::LocalTensor<T> rowLocal = outQueue.DeQue<T>();

                    for (int64_t r = 0; r < repeats; ++r) {
                        int64_t dstOffset = dstBase + (srcIdx * repeats + r) * innerSize + t * tileLength;
                        CopyOut(dstOffset, rowLocal, curTileLen);
                    }

                    outQueue.FreeTensor(rowLocal);
                }
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t srcOffset, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> local = inQueue.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{
            1,
            static_cast<uint32_t>(curTileLength * sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(local, selfGm[srcOffset], copyParams, padParams);
        inQueue.EnQue(local);
    }

    __aicore__ inline void CopyOut(int64_t dstOffset, AscendC::LocalTensor<T> &local, int64_t curTileLength)
    {
        AscendC::DataCopyExtParams copyParams{
            1,
            static_cast<uint32_t>(curTileLength * sizeof(T)),
            0, 0, 0
        };
        AscendC::DataCopyPad(outGm[dstOffset], local, copyParams);
    }

